from modele import chapitre,E,Q,tableau

chapitre(10,'statistiques','Statistiques et diagrammes','3 · Données et hasard',
'Effectifs · Fréquences · Moyenne · Médiane',
['Organiser et représenter des données.','Calculer une médiane sur une petite série.','Interpréter moyennes, fréquences et diagrammes circulaires.'],
['Pourcentages et angles.'],[
r'''\essSection{1}{Décrire une série}
\begin{definition}L’effectif d’une valeur est le nombre de fois où elle apparaît. L’effectif total est la somme des effectifs. La fréquence d’une valeur est son effectif divisé par l’effectif total. Les fréquences de toutes les catégories distinctes ont pour somme 1.\end{definition}
\begin{propriete}La moyenne se calcule en divisant la somme de toutes les valeurs par leur nombre. Si les valeurs ont des effectifs, on calcule la somme des produits valeur $\times$ effectif puis on divise par l’effectif total.\end{propriete}
\begin{definition}Après avoir rangé les valeurs, une médiane partage la série en deux parties contenant chacune au moins la moitié des données, au sens « inférieures ou égales » et « supérieures ou égales ». Pour un effectif impair, on prend la valeur centrale ; pour un effectif pair, ce livre prend la moyenne des deux valeurs centrales.\end{definition}
\begin{exemple}Pour $2,4,4,7,8$, la médiane est la 3e valeur, soit 4 ; la moyenne vaut $25/5=5$. Pour $2,4,7,9$, on choisit comme médiane $(4+7)/2=5{,}5$. La médiane n’est pas toujours une valeur observée.\end{exemple}''',
r'''\essSection{2}{Représenter et interpréter}
\begin{propriete}Dans un diagramme circulaire complet, l’angle d’un secteur vaut fréquence $\times360^\circ$. La somme des angles vaut $360^\circ$. Une fréquence de 25\,\% donne ainsi $90^\circ$.\end{propriete}
@FIG:cours-camembert@
\begin{savoirfaire}[Choisir un graphique]Un diagramme en bâtons compare des effectifs par valeur. Un diagramme circulaire montre le partage d’un total en catégories. Ajouter titre, légende, unités et graduations. Un tableur-grapheur peut construire ces représentations à partir d’un tableau.\end{savoirfaire}
\begin{attention}Toujours identifier le total de référence. Deux groupes de tailles différentes ne se comparent pas seulement avec leurs effectifs. La moyenne est sensible aux valeurs très grandes ; la médiane renseigne sur le centre de la série ordonnée, sans dire que toutes les valeurs sont proches.\end{attention}'''],[
E('Un effectif total',r"Les notes 8, 10, 12 ont respectivement pour effectifs 3, 5, 2. Donner l’effectif total et la fréquence de la note 10.",r"Le total vaut $3+5+2=\res{10}$. La fréquence de 10 est $5/10=\res{0{,}5}$, soit 50\,\%.","Additionner les effectifs avant de calculer la fréquence.","assert 3+5+2==10 and Rational(5,10)==Rational(1,2)"),
E('Une moyenne simple',r"Calculer la moyenne de 6, 9, 10 et 15.",r"La somme vaut $6+9+10+15=40$. On divise par quatre valeurs : $40/4=\res{10}$.","Additionner toutes les valeurs et compter les données.","assert Rational(6+9+10+15,4)==10"),
E('Une médiane impaire',r"Déterminer une médiane de la série : 12, 7, 9, 15, 8.",r"La série rangée est $7,8,9,12,15$. L’effectif est 5 : la 3e valeur est centrale. La médiane vaut $\res9$.","Ranger avant de chercher le rang central.","assert sorted([12,7,9,15,8])[2]==9"),
E('Une médiane paire',r"Déterminer la médiane choisie dans ce livre pour : 3, 4, 8, 10, 12, 15.",r"Il y a six valeurs déjà rangées. Les valeurs centrales sont aux rangs 3 et 4 : 8 et 10. Leur moyenne vaut $\res9$. Trois données sont au plus 9 et trois sont au moins 9.","Repérer les deux rangs centraux.","assert Rational(8+10,2)==9"),
E('Un secteur circulaire',r"Un sport regroupe 30\,\% des inscrits. Quel angle lui attribuer dans un diagramme circulaire complet ?",r"$30/100\times360=\res{108^\circ}$. L’angle est proportionnel à la part du total.","Prendre la fraction correspondante de 360 degrés.","assert Rational(30,100)*360==108"),
E('Une moyenne avec effectifs',r"Les valeurs 2, 5 et 8 ont pour effectifs 4, 3 et 3. Calculer la moyenne.",r"L’effectif total vaut 10. La somme pondérée est $2\times4+5\times3+8\times3=47$. La moyenne est $47/10=\res{4{,}7}$. Il ne faut pas moyenner seulement 2, 5 et 8.","Tenir compte des répétitions.","assert Rational(2*4+5*3+8*3,10)==Rational('4.7')"),
E('Lire un diagramme en bâtons',r"Le diagramme donne les nombres de livres lus par 12 élèves. Déterminer la médiane.",r"Les effectifs sont 2 pour 0 livre, 4 pour 1, 3 pour 2, 2 pour 3 et 1 pour 4. Les rangs 6 et 7 valent respectivement 1 et 2. La médiane choisie est donc $(1+2)/2=\res{1{,}5}$ livre.","Cumuler les effectifs pour retrouver les rangs.","assert sorted([0]*2+[1]*4+[2]*3+[3]*2+[4])[5:7]==[1,2]",figure='stat-livres'),
E('Construire le partage',r"Sur 40 élèves, 20 choisissent le football, 12 le basket et 8 le tennis. Construire le diagramme circulaire.",r"Les fréquences sont $1/2$, $3/10$, $1/5$. Les angles correspondants sont $\res{180^\circ,\ 108^\circ,\ 72^\circ}$. Leur somme vaut 360 degrés. On construit les secteurs à la suite et on ajoute une légende.","Transformer chaque fréquence en angle.","assert [Rational(a,40)*360 for a in [20,12,8]]==[180,108,72]",figure='stat-sports'),
E('Lire un pourcentage',r"Dans le diagramme, le secteur A mesure $144^\circ$. Il y a 75 réponses au total. Combien correspondent à A ?",r"La fréquence de A vaut $144/360=0{,}4=40\,\%$. Son effectif vaut donc $75\times0{,}4=\res{30}$.","Passer de l’angle à la fréquence puis à l’effectif.","assert Rational(144,360)*75==30",figure='stat-secteur-a'),
E('Une formule de tableur',r"Les valeurs sont en A2:A4 et leurs effectifs en B2:B4. Proposer une méthode avec une colonne C pour calculer la moyenne.",r"En C2, saisir $\res{\texttt{=A2*B2}}$ puis recopier jusqu’à C4. La moyenne se calcule avec $\res{\texttt{=SOMME(C2:C4)/SOMME(B2:B4)}}$. Les produits valeur-effectif représentent la somme des données répétées.","Construire les produits avant de les additionner.","assert Rational(2*4+5*3+8*3,4+3+3)==Rational('4.7')"),
E('Ajouter une valeur',r"Cinq élèves ont une moyenne de 12 à un jeu. Un sixième rejoint le groupe avec 18. Quelle est la nouvelle moyenne ?",r"La somme initiale vaut $5\times12=60$. La nouvelle somme vaut $60+18=78$, pour 6 élèves. La moyenne est $78/6=\res{13}$. Moyenner 12 et 18 donnerait un mauvais poids aux cinq premiers élèves.","Retrouver la somme à partir de la moyenne.","assert Rational(5*12+18,6)==13"),
E('Une valeur manquante',r"Les nombres 8, 11, 14 et $x$ ont une moyenne de 12. Trouver $x$, puis la médiane de la série.",r"La somme doit valoir $4\times12=48$. Donc $x=48-(8+11+14)=\res{15}$. La série rangée est $8,11,14,15$ et la médiane choisie vaut $(11+14)/2=\res{12{,}5}$.","Utiliser la moyenne pour retrouver le total.","assert 4*12-(8+11+14)==15 and Rational(11+14,2)==Rational('12.5')"),
E('Une valeur extrême',r"Comparer moyenne et médiane des séries A : 4, 5, 6, 7, 8 et B : 4, 5, 6, 7, 38.",r"Pour A, moyenne et médiane valent 6. Pour B, la somme vaut 60 donc la moyenne vaut 12 ; la valeur centrale reste 6. La seule modification du dernier nombre change fortement la moyenne, sans changer la médiane.","Calculer séparément les deux indicateurs.","assert sum([4,5,6,7,8])/5==6 and sum([4,5,6,7,38])/5==12"),
E('Comparer deux groupes',r"Dans A, 18 élèves sur 24 pratiquent un sport. Dans B, 21 sur 30 en pratiquent un. Quel groupe a la plus forte proportion de sportifs ?",r"A a une proportion $18/24=75\,\%$ et B $21/30=70\,\%$. A a donc la plus forte proportion, même si B compte davantage de sportifs. Les effectifs totaux sont différents.","Comparer des fréquences plutôt que des nombres bruts.","assert Rational(18,24)==Rational(75,100)>Rational(21,30)==Rational(70,100)"),
E('Interpréter une médiane',r"Dans une série de 20 durées, la médiane choisie vaut 15 min. Peut-on conclure que dix durées valent exactement 15 min ? Donner un exemple qui justifie.",r"Non : une médiane parle de position dans la série, pas du nombre de valeurs égales à 15. Par exemple, dix durées de 10 min et dix de 20 min donnent une médiane $(10+20)/2=15$ min, sans aucune durée égale à 15.","Distinguer valeur centrale et fréquence d’une valeur.","assert Rational(10+20,2)==15 and 15 not in [10]*10+[20]*10")
],reperes=['Effectifs, fréquences et moyenne','Médiane sur un effectif au plus égal à 30','Diagrammes circulaires et en bâtons','Tableur et interprétation critique'],deco='statistiques')

chapitre(11,'probabilites','Probabilités : comprendre le hasard','3 · Données et hasard',
'Issues · Événements · Équiprobabilité · Contraire',
['Décrire une expérience aléatoire et ses issues.','Calculer une probabilité avec un modèle explicite.','Utiliser l’événement contraire et différentes écritures.'],
['Fractions, pourcentages et aires simples.'],[
r'''\essSection{1}{Décrire les possibilités}
\begin{definition}Une expérience aléatoire a plusieurs résultats possibles sans que l’on puisse prévoir avec certitude celui qui se produira. Chaque résultat possible est une issue. Un événement regroupe des issues qui répondent à une condition.\end{definition}
\begin{propriete}Une probabilité est un nombre compris entre 0 et 1. L’événement impossible a pour probabilité 0 ; l’événement certain a pour probabilité 1. La somme des probabilités de toutes les issues distinctes vaut 1.\end{propriete}
\begin{propriete}Si toutes les issues ont la même probabilité, on parle d’équiprobabilité. La probabilité d’un événement vaut alors le nombre d’issues favorables divisé par le nombre total d’issues. Cette formule nécessite de justifier pourquoi les issues comptées ont la même chance.\end{propriete}
\begin{exemple}Dans un sac de 3 boules rouges et 2 bleues, indiscernables au toucher et tirées au hasard, la probabilité de rouge vaut $3/5$. Les deux couleurs ne sont pas équiprobables ; les cinq boules le sont.\end{exemple}''',
r'''\essSection{2}{Utiliser un modèle cohérent}
\begin{definition}L’événement contraire de A regroupe toutes les issues qui ne réalisent pas A. Il se note ici « non A ». Les deux probabilités ont pour somme 1 : $P(\text{non A})=1-P(A)$.\end{definition}
\begin{exemple}Si la probabilité de gagner vaut 0,35 et s’il n’y a que gain ou perte, la probabilité de perdre vaut $1-0{,}35=0{,}65$, soit 65\,\%. Pour un dé équilibré, « ne pas obtenir 6 » a pour probabilité $5/6$.\end{exemple}
@FIG:cours-urne@
\begin{savoirfaire}[Cas non équiprobable]Les probabilités peuvent être données par un modèle, par exemple 0,2 pour une face et 0,8 pour une autre. Pour une cible où le point d’impact est uniforme sur toute l’aire, une probabilité se calcule comme un rapport d’aires.\end{savoirfaire}
\begin{attention}Le résultat d’un essai ne change pas une probabilité annoncée pour des essais indépendants dans les mêmes conditions. Une fréquence observée est un résultat expérimental, pas une garantie sur le prochain tirage. Les calculs de ce chapitre portent sur une seule épreuve.\end{attention}'''],[
E('Un dé équilibré',r"On lance un dé équilibré numéroté de 1 à 6. Énumérer les issues, puis calculer la probabilité d’obtenir 4.",r"Les issues sont 1, 2, 3, 4, 5 et 6. Elles sont équiprobables puisque le dé est équilibré. Une seule est favorable : $\res{P(4)=1/6}$.","Identifier les issues équiprobables.","assert Rational(1,len(range(1,7)))==Rational(1,6)"),
E('Un événement',r"Sur ce dé, calculer la probabilité d’obtenir un nombre strictement supérieur à 4.",r"Les issues favorables sont 5 et 6, soit deux sur six. La probabilité vaut $2/6=\res{1/3}$. « Strictement » exclut la valeur 4.","Traduire précisément la condition.","assert [a for a in range(1,7) if a>4]==[5,6]"),
E('Certain et impossible',r"Sur un dé classique, donner un événement certain et un événement impossible.",r"« Obtenir un nombre inférieur à 7 » est certain : probabilité $\res1$. « Obtenir 8 » est impossible : probabilité $\res0$. Ces valeurs encadrent toutes les probabilités.","Comparer l’événement à la liste des issues.","assert all(a<7 for a in range(1,7)) and 8 not in range(1,7)"),
E('Plusieurs écritures',r"Une probabilité vaut $3/8$. L’écrire sous forme décimale et en pourcentage.",r"$3/8=\res{0{,}375}$, soit $\res{37{,}5\,\%}$. Les trois écritures représentent la même probabilité.","Passer de la fraction au quotient puis au pourcentage.","assert Rational(3,8)==Rational('.375') and Rational(3,8)*100==Rational('37.5')"),
E('Le contraire',r"Un jeu a une probabilité de gain de 0,28. Il ne peut y avoir que gain ou perte. Quelle est la probabilité de perte ?",r"Perdre est ici l’événement contraire de gagner. Sa probabilité est $1-0{,}28=\res{0{,}72}$, soit 72\,\%. L’absence de résultat nul est nécessaire pour cette conclusion.","Vérifier que les événements sont bien contraires.","assert 1-Rational('.28')==Rational('.72')"),
E('Une urne',r"Une urne contient 4 rouges, 3 bleues et 1 verte, indiscernables au toucher. On tire une boule au hasard. Calculer les probabilités de rouge et de non-rouge.",r"Le total vaut 8. $P(R)=4/8=\res{1/2}$. Le contraire contient les 3 bleues et la verte : $P(\text{non R})=4/8=\res{1/2}$. Compter trois couleurs ne donnerait pas trois chances égales.","Compter les objets équiprobables.","assert Rational(4,8)==Rational(3+1,8)==Rational(1,2)",figure='urne-431'),
E('Une roue',r"Une roue comporte 8 secteurs de même angle, numérotés de 1 à 8 et supposés équiprobables. Calculer la probabilité d’obtenir un multiple de 3.",r"Les numéros favorables sont 3 et 6. Deux secteurs sur huit conviennent : $2/8=\res{1/4}$. L’égalité des chances est donnée par le modèle.","Repérer les secteurs favorables.","assert [a for a in range(1,9) if a%3==0]==[3,6]",figure='roue-8'),
E('Des faces inégales',r"Un objet a trois issues A, B, C de probabilités respectives 0,2 ; 0,5 ; $p$. Trouver $p$ et la probabilité de ne pas obtenir B.",r"Le total des trois probabilités vaut 1, donc $p=1-0{,}2-0{,}5=\res{0{,}3}$. Le contraire de B a pour probabilité $1-0{,}5=\res{0{,}5}$. On ne compte pas simplement un tiers par issue.","Utiliser la somme des probabilités.","assert 1-Rational('.2')-Rational('.5')==Rational('.3')"),
E('Une cible carrée',r"Un point est choisi uniformément sur une cible carrée de côté 10 cm. Une zone gagnante est un carré de côté 4 cm entièrement à l’intérieur. Calculer la probabilité de gagner.",r"L’aire totale est 100 cm$^2$ et l’aire gagnante 16 cm$^2$. Avec le choix uniforme, la probabilité vaut $16/100=\res{0{,}16}$, soit 16\,\%. Les longueurs seules ne sont pas le bon rapport.","Comparer les aires dans le modèle uniforme.","assert Rational(4**2,10**2)==Rational('.16')",figure='cible-carree'),
E('Une observation',r"Sur 50 lancers d’une pièce annoncée équilibrée, on observe 31 piles. Quelle est la fréquence ? Doit-on annoncer que la probabilité du prochain pile vaut 31/50 ?",r"La fréquence observée est $31/50=\res{0{,}62}$. Le modèle annoncé reste une probabilité de pile de $\res{1/2}$ au prochain lancer indépendant. Une fréquence sur un nombre fini d’essais peut s’écarter de la probabilité.","Séparer observation et modèle.","assert Rational(31,50)==Rational('.62') and Rational(31,50)!=Rational(1,2)"),
E('Un effectif inconnu',r"Un sac contient 5 boules rouges et un nombre $b$ de bleues. Un tirage au hasard donne une probabilité de rouge égale à $1/4$. Trouver $b$.",r"Rouge représente un quart du total, donc le sac contient $5\times4=20$ boules. Les bleues sont $20-5=\res{15}$. Contrôle : $5/(5+15)=1/4$.","Retrouver le total à partir de la part rouge.","assert Rational(5,5+15)==Rational(1,4)"),
E('Une couronne gagnante',r"Une cible est un disque de rayon 6 cm. La zone gagnante est la couronne extérieure au disque concentrique de rayon 3 cm. Le point d’impact est uniforme. Calculer la probabilité de gagner.",r"L’aire totale est $36\pi$ et le disque intérieur $9\pi$. La couronne a pour aire $27\pi$. La probabilité vaut $27\pi/(36\pi)=\res{3/4}$, soit 75\,\%. On peut aussi prendre le contraire du disque intérieur.","Soustraire les aires avant de prendre le rapport.","assert simplify((pi*6**2-pi*3**2)/(pi*6**2))==Rational(3,4)",figure='cible-couronne'),
E('Changer la composition',r"Une urne contient 3 rouges et 5 bleues. On ajoute seulement des rouges pour que la probabilité de rouge devienne $1/2$. Combien faut-il en ajouter ?",r"Pour que les deux couleurs soient équiprobables, il faut autant de rouges que de bleues. Les bleues restent 5 ; il faut donc ajouter $\res2$ rouges. Le total augmente aussi : $5/(5+5)=1/2$.","Modifier à la fois le favorable et le total.","assert Rational(3+2,3+5+2)==Rational(1,2)"),
E('Une roue non uniforme',r"Une roue circulaire a trois secteurs de $90^\circ$, $120^\circ$ et $150^\circ$. L’arrêt est uniforme en angle. Calculer la probabilité du dernier secteur, puis celle de ne pas l’obtenir.",r"La probabilité du secteur de $150^\circ$ vaut $150/360=\res{5/12}$. Son contraire vaut $1-5/12=\res{7/12}$. Les trois secteurs n’ont pas la même probabilité car leurs angles diffèrent.","Prendre la part de l’angle total.","assert Rational(150,360)==Rational(5,12) and 1-Rational(5,12)==Rational(7,12)",figure='roue-inegale'),
E('Des numéros et des couleurs',r"Un sac contient six jetons équiprobables : R1, R2, R3, B1, B2, V1. Calculer la probabilité de « rouge ou portant le numéro 1 ». Pourquoi ne peut-on pas additionner directement les deux probabilités ?",r"Les jetons favorables sont R1, R2, R3, B1 et V1 : $\res{5/6}$. Rouge a pour probabilité $3/6$ et numéro 1 aussi, mais R1 appartient aux deux événements. Leur addition le compterait deux fois. L’énumération des jetons évite ce doublon.","Énumérer les issues favorables sans répétition.","assert len(set(['R1','R2','R3'])|set(['R1','B1','V1']))==5",figure='jetons-numerotes')
],reperes=['Vocabulaire et probabilités entre 0 et 1','Équiprobabilité et écritures diverses','Événements contraires','Modèles non équiprobables et aires'],deco='probabilites')

chapitre(12,'triangles','Construire et comparer des triangles','4 · Géométrie et espace',
'Cas d’égalité · Codages · Protocoles · Preuves',
['Construire un triangle avec des données suffisantes.','Reconnaître les trois cas d’égalité des triangles.','Rédiger une preuve en associant les sommets.'],
['Angles du triangle, inégalité triangulaire et médiatrice.'],[
r'''\essSection{1}{Les cas d’égalité}
\begin{definition}Deux triangles sont égaux s’ils peuvent se superposer : leurs côtés correspondants et leurs angles correspondants sont égaux. L’ordre des sommets doit respecter cette correspondance.\end{definition}
\begin{propriete}Trois critères suffisent : trois côtés respectivement égaux (CCC) ; deux côtés et l’angle compris respectivement égaux (CAC) ; un côté et les deux angles à ses extrémités respectivement égaux (ACA). Une figure retournée peut rester superposable.\end{propriete}
@FIG:cours-triangles-egaux@
\begin{attention}Deux longueurs seules ne fixent pas un triangle. Trois angles fixent une forme, mais pas une taille. Pour CAC, il faut bien l’angle situé entre les deux côtés connus ; un autre angle ne garantit pas le critère.\end{attention}''',
r'''\essSection{2}{Construire et démontrer}
\begin{savoirfaire}[Un protocole CCC]Pour $AB=6$, $AC=5$, $BC=4$ cm : tracer $[AB]$, puis le cercle de centre A et de rayon 5, puis celui de centre B et de rayon 4. Une intersection est C ; relier. L’autre intersection donne une figure symétrique, donc un triangle égal.\end{savoirfaire}
\begin{savoirfaire}[Vérifier l’existence]La plus grande longueur doit être strictement inférieure à la somme des deux autres pour un triangle non aplati. Pour une construction avec angles, leur somme doit être compatible avec les $180^\circ$ d’un triangle.\end{savoirfaire}
\begin{exemple}[Rédiger une preuve]On écrit les trois égalités de données, on nomme le cas utilisé et l’on conclut que les triangles sont égaux dans l’ordre choisi. On peut alors transférer une longueur ou un angle correspondant. Le dessin aide à chercher mais ne remplace pas ces raisons.\end{exemple}
\begin{savoirfaire}[Utiliser un outil]À la règle, au compas et au rapporteur, laisser les traits utiles. Sur un logiciel de géométrie, construire avec les contraintes (cercle, angle, parallèle), puis déplacer un point pour contrôler la stabilité. Une mesure visuelle seule ne démontre pas une propriété.\end{savoirfaire}'''],[
E('Vérifier un triangle',r"Peut-on construire un triangle de côtés 4, 5 et 6 cm ? Proposer la première étape.",r"La plus grande longueur est 6 et $4+5=9>6$ : le triangle existe. On peut tracer d’abord le côté de 6 cm, puis utiliser les deux autres longueurs comme rayons de cercles.","Tester l’inégalité triangulaire.","assert 4+5>6",figure='tri-01'),
E('Un triangle impossible',r"Peut-on construire un triangle non aplati de côtés 2, 3 et 6 cm ?",r"Non : la plus grande longueur 6 dépasse $2+3=5$. Les deux petits segments ne peuvent rejoindre les extrémités du grand côté. L’inégalité triangulaire n’est pas respectée.","Comparer le plus grand côté à la somme des autres.","assert 2+3<6",figure='tri-02'),
E('Deux côtés et un angle',r"Construire $AB=5$ cm, $AC=4$ cm et $\widehat{BAC}=60^\circ$. Nommer le type de données.",r"Tracer $AB=5$ cm. En A, construire une demi-droite formant $60^\circ$ avec $[AB)$. Y placer C à 4 cm de A, puis relier B à C. Les données sont deux côtés et leur angle compris : cas $\res{CAC}$.","Placer le sommet de l’angle connu.","assert 5>0 and 4>0 and 0<60<180",figure='tri-03'),
E('Un côté et deux angles',r"Construire $AB=6$ cm, $\widehat{BAC}=50^\circ$ et $\widehat{ABC}=60^\circ$. Calculer le troisième angle.",r"Tracer AB. En A et B, tracer les demi-droites formant les angles demandés dans le même demi-plan. Leur intersection est C. $\widehat{ACB}=180-50-60=\res{70^\circ}$. Les données correspondent au cas ACA.","Utiliser la somme des angles du triangle.","assert 180-50-60==70",figure='tri-04'),
E('Trois côtés correspondants',r"On donne $AB=DE=4$, $AC=DF=5$, $BC=EF=6$ cm. Les triangles ABC et DEF sont-ils égaux ? Écrire la correspondance.",r"Les trois côtés sont respectivement égaux : cas CCC. On associe A à D, B à E et C à F ; les triangles ABC et DEF sont égaux. On en déduit notamment $\widehat{ABC}=\widehat{DEF}$.","Associer les sommets à partir des côtés communs.","assert [4,5,6]==[4,5,6]",figure='tri-05'),
E('Un angle compris',r"On donne $AB=DE=5$ cm, $AC=DF=3$ cm et $\widehat{BAC}=\widehat{EDF}=40^\circ$. Justifier l’égalité des triangles et en déduire une égalité de côtés.",r"Les angles connus sont compris entre les deux côtés égaux. Le critère CAC donne l’égalité de ABC et DEF, avec A correspondant à D. Les troisièmes côtés sont donc égaux : $\res{BC=EF}$.","Vérifier le rôle de l’angle avant d’utiliser CAC.","assert 0<40<180 and 5==5 and 3==3",figure='tri-06'),
E('Deux angles aux extrémités',r"$AB=DE=6$ cm, $\widehat A=\widehat D=50^\circ$ et $\widehat B=\widehat E=60^\circ$. Montrer que $\widehat C=\widehat F$ et que les triangles sont égaux.",r"Chaque troisième angle vaut $180-50-60=\res{70^\circ}$. Le côté AB correspond à DE et les angles à ses extrémités sont égaux : cas ACA. Les triangles ABC et DEF sont donc égaux.","Citer le côté encadré par les deux angles.","assert 180-50-60==70",figure='tri-07'),
E('Des données insuffisantes',r"Deux triangles ont chacun deux côtés de longueurs 5 et 4 cm. Peut-on conclure qu’ils sont égaux ?",r"Non. L’angle compris entre ces côtés peut changer, ce qui change le troisième côté. Les deux positions représentées fournissent deux formes différentes malgré les mêmes deux longueurs. Il manque une donnée suffisante.","Chercher une variation conservant les données.","assert simplify(25+16-2*5*4*cos(pi/3))!=simplify(25+16-2*5*4*cos(pi/2))",figure='tri-08'),
E('Un triangle isocèle',r"ABC est isocèle en A, avec $AB=AC$ et $\widehat{BAC}=74^\circ$. Déterminer les deux autres angles.",r"Les angles à la base B et C sont égaux. Leur somme vaut $180-74=106^\circ$ ; chacun vaut $106/2=\res{53^\circ}$. On utilise une propriété du triangle isocèle, cohérente avec sa symétrie.","Répartir la somme restante en deux angles égaux.","assert Rational(180-74,2)==53",figure='tri-09'),
E('Un parallélogramme coupé',r"ABCD est un parallélogramme et l’on trace la diagonale AC. Montrer que les triangles ABC et CDA sont égaux.",r"Dans un parallélogramme, $AB=CD$ et $BC=DA$. Le côté AC est commun aux deux triangles. Le cas CCC montre l’égalité de ABC et CDA, avec A correspondant à C, B à D et C à A.","Utiliser les côtés opposés et le côté commun.","assert [6,4,7]==[6,4,7]",figure='tri-10'),
E('Un cerf-volant',r"$AB=DB=5$ cm et $AC=DC=4$ cm. Les points A et D sont de part et d’autre de (BC). Montrer que $\widehat{BAC}=\widehat{BDC}$.",r"Les triangles ABC et DBC partagent BC. Avec $AB=DB$ et $AC=DC$, leurs trois côtés sont respectivement égaux. Le cas CCC donne l’égalité des triangles ; A correspond à D. Les angles demandés sont donc égaux.","Transférer un angle après avoir prouvé l’égalité.","assert [5,4,6]==[5,4,6]",figure='tri-11'),
E('Une hauteur et une aire',r"Dans le triangle ABC, $AB=8$ cm et la hauteur CH vaut 3 cm. Calculer l’aire. Expliquer pourquoi AC ne peut pas remplacer CH dans la formule sans information supplémentaire.",r"$\mathcal A=AB\times CH/2=8\times3/2=\res{12\ \mathrm{cm}^2}$. La hauteur CH est perpendiculaire à la droite de la base AB. Le côté AC ne possède pas nécessairement cette propriété.","Associer une base à sa hauteur perpendiculaire.","assert Rational(8*3,2)==12",figure='tri-12'),
E('Un périmètre transféré',r"Les triangles ABC et DEF sont égaux, avec A correspondant à D, B à E et C à F. On sait $AB=7$, $EF=5$ et $DF=4$ cm. Calculer le périmètre de ABC.",r"Par correspondance, $BC=EF=5$ et $AC=DF=4$. Le périmètre est $7+5+4=\res{16\ \mathrm{cm}}$. Il faut respecter les sommets associés pour transférer les données.","Compléter les côtés grâce à la correspondance.","assert 7+5+4==16 and 5+4>7",figure='tri-13'),
E('Réparer un protocole',r"On veut $AB=6$ cm, $AC=4$ cm et $\widehat{BAC}=35^\circ$. Un protocole place un angle de $35^\circ$ en B. Corriger et expliquer le problème.",r"Le sommet de $\widehat{BAC}$ est A, lettre du milieu. L’angle de $35^\circ$ doit donc être construit en A entre AB et la demi-droite portant AC. Placer cet angle en B ne respecte pas la donnée et ne construit pas nécessairement le triangle demandé.","Lire le sommet au milieu du nom de l’angle.","assert 'BAC'[1]=='A'",figure='tri-14'),
E('Démontrer une perpendicularité',r"ABC est isocèle en A. M est le milieu de [BC]. Démontrer que (AM) est perpendiculaire à (BC) en utilisant l’égalité de deux triangles.",r"$AB=AC$, $BM=CM$ car M est le milieu, et AM est commun. Les triangles ABM et ACM sont égaux par CCC. Donc $\widehat{AMB}=\widehat{AMC}$. Ces deux angles adjacents forment un angle plat car B, M, C sont alignés : chacun vaut $90^\circ$. Ainsi $\res{(AM)\perp(BC)}$.","Comparer deux triangles puis utiliser l’alignement.","assert Rational(180,2)==90",figure='tri-15')
],reperes=['Existence et protocoles de construction','Trois cas d’égalité des triangles','Correspondance de côtés et d’angles','Raisonnements et preuves géométriques'],deco='geometrie')
